"""Transfer cents to account using ledger.post with wire-encoded amount."""
import ledger

_check_digit = lambda d: sum(int(c) for c in d) % 10

def _encode(cents: int) -> str:
    if not isinstance(cents, int):
        raise TypeError("cents must be an int")
    sign = '+' if cents >= 0 else '-'
    digits = str(abs(cents))
    check = _check_digit(digits)
    return f"{sign}{digits}#{check}"

def transfer(acct: str, cents: int, reason: str) -> int:
    encoded = _encode(cents)
    return ledger.post(acct, encoded, memo=reason)

